export const toLocalISODate=t=>`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")}`;export const q=t=>document.querySelector(t);export const debounce=(t,r=140)=>{let e=0;return(...n)=>{window.clearTimeout(e),e=window.setTimeout((()=>t(...n)),r)}};export const formatError=t=>{if(!t)return"Неизвестная ошибка";if(t instanceof Error)return t.message||t.name||"Ошибка";if("string"==typeof t)return t;try{return JSON.stringify(t)}catch(r){return String(t)}};